from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info


@pretty_log
def check_if_second_measurement_is_lower(first: float, second: float, min_percent_delta: float):
    """
    Checks whether second measurement is lower than first one by at least percentage value of min delta.
    :param first: first measurement used in comparison; expected to be the larger of two; i.e. 15.3
    :param second: second measurement used in comparison; expected to be the smaller of two; i.e. 14.8
    :param min_percent_delta: minimal acceptable delta (in percents) between compared measurements; i.e 2.5 (meaning 2,5%)
    :raises ResultError: if second is not lower than first by min delta
    """
    log_info(f'Checking if measurement {second} is lower than {first} by at least {min_percent_delta}%', to_console=True)
    delta = first - second
    percent_delta = delta / first * 100

    if percent_delta < min_percent_delta:
        raise ResultError(f'Measurement {second} is not lower than measurement {first} by at least {min_percent_delta}%')


@pretty_log
def check_if_second_measurement_is_higher(first: float, second: float, min_delta: float, max_delta: float):
    """
    Checks whether second measurement is higher than first one by at least min delta and no more than max delta.
    :param first: first measurement used in comparison; expected to be the smaller of two; i.e. 14.8
    :param second: second measurement used in comparison; expected to be the larger of two; i.e. 15.3
    :param min_delta: minimal acceptable delta between compared measurements; i.e. 2.5
    :param max_delta: maximal acceptable delta between compared measurements; i.e. 3.1
    :raises ResultError: if second is not higher than first by min delta or is higher than first by more than max delta
    """
    log_info(f'Checking if measurement {second} is higher than {first} by at least {min_delta} and no more than {max_delta}', to_console=True)
    delta = second - first
    error_msg = None

    if delta < min_delta:
        error_msg = f'Measurement {second} is not higher than measurement {first} by at least {min_delta}'

    if delta > max_delta:
        error_msg = f'Measurement {second} is higher than measurement {first} by more than {max_delta}'

    if error_msg:
        raise ResultError(error_msg)


@pretty_log
def check_if_measurements_are_equal(first: float, second: float, max_percent_delta: float):
    """
    Checks whether two measurements are equal or different by no more than percentage value of max delta.
    :param first: first measurement used in comparison; i.e. 15.3
    :param second: second measurement used in comparison; i.e. 14.8
    :param max_percent_delta: maximal acceptable delta (in percents) between compared measurements; i.e. 1.2 (meaning 1,2%)
    :raises ResultError: if compared measurements differ by more than max delta
    """
    log_info(f'Checking if measurements {first} and {second} are equal or not differ by more than {max_percent_delta}%',
             to_console=True)
    delta = abs(first - second)
    percent_delta = delta / ((first + second) / 2) * 100

    if percent_delta > max_percent_delta:
        raise ResultError(f'Measurements {first} and {second} are not the same - '
                          f'maximal delta of {max_percent_delta}% was exceeded')


def is_measurement_numeric(value: str) -> bool:
    """
    Checks whether measurement is a numeric value (integer or float, positive or negative).
    :param value: measurement which should be checked, i.e. '-0.5'
    :return: True if measurement is a numeric value, False otherwise
    """
    try:
        float(str(value))
        return True
    except ValueError:
        return False
